package medium;public class KthSmallestElementInSortedMatrix{public static int kthSmallest(int[][]m,int k){java.util.PriorityQueue<int[]>pq=new java.util.PriorityQueue<>((a,b)->a[0]-b[0]);pq.offer(new int[]{m[0][0],0,0});while(k>1){int[]curr=pq.poll();k--;if(curr[1]+1<m.length)pq.offer(new int[]{m[curr[1]+1][curr[2]],curr[1]+1,curr[2]});if(curr[2]+1<m[0].length&&curr[1]==0)pq.offer(new int[]{m[curr[1]][curr[2]+1],curr[1],curr[2]+1});}return pq.peek()[0];}public static void main(String[]args){System.out.println("Kth: "+kthSmallest(new int[][]{{1,2},{1,1}},1));}}
